+document.addEventListener("DOMContentLoaded", function () {
    const getTxId = () => "tx-" + Date.now() + "-" + Math.floor(Math.random() * 100000);

    // Helper para tracking de clics
    const trackClick = (selector, eventData) => {
        document.querySelectorAll(selector).forEach(el => {
            el.addEventListener("click", () => gtag("event", "conversion", eventData));
        });
    };

    trackClick('a[href*="wa.link"], a[href*="wa.me"]', { 'send_to': 'AW-950025686/G5d9COv-gYABENb7gMUD' });
    trackClick('a[href^="tel:"]', { 'send_to': 'AW-950025686/7f5OCLWNlYABENb7gMUD', 'value': 200, 'currency': 'ARS', 'transaction_id': getTxId() });
    trackClick('.btn-reserve', { 'send_to': 'AW-950025686/JX0xCOX-gYABENb7gMUD', 'value': 10, 'currency': 'ARS', 'transaction_id': getTxId() });

    // Lazy Load HubSpot
    const loadHS = () => {
        const script = document.createElement("script");
        script.src = "https://js.hsforms.net/forms/embed/50609640.js";
        script.defer = true;
        script.onerror = () => {
            const frame = document.querySelector(".hs-form-frame");
            if (frame) {
                frame.innerHTML = '<div class="text-center p-4"><h5>Error de carga</h5><button id="hs-retry" class="btn btn-outline-primary btn-sm">Reintentar</button></div>';
                document.getElementById("hs-retry").onclick = loadHS;
            }
        };
        document.body.appendChild(script);
    };

    const observer = new IntersectionObserver(entries => {
        if (entries[0].isIntersecting) {
            loadHS();
            observer.disconnect();
        }
    }, { rootMargin: "200px" });

    const contactSection = document.getElementById("contacto");
    if (contactSection) observer.observe(contactSection);

    window.addEventListener("message", function (event) {
        if (event.data.type === 'hsFormCallback' && event.data.eventName === 'onFormSubmitted') {
            gtag('event', 'conversion', { 'send_to': 'AW-950025686/GSNXCJ-IrKMBENb7gMUD', 'value': 150, 'currency': 'ARS', 'transaction_id': getTxId() });
        }
    });

    // Lógica para el listado dinámico de Partidos (Destinos)
    const partidos = [
        "Almirante Brown", "Avellaneda", "Berazategui", "Berisso", "Brandsen", "Campana", "Cañuelas", "Ensenada", "Escobar", "Esteban Echeverría",
        "Exaltación de la Cruz", "Ezeiza", "Florencio Varela", "General Las Heras", "General Rodríguez", "General San Martín", "Hurlingham", "Ituzaingó", "José C. Paz", "La Matanza",
        "La Plata", "Lanús", "Lomas de Zamora", "Luján", "Malvinas Argentinas", "Marcos Paz", "Merlo", "Moreno", "Morón", "Pilar",
        "Presidente Perón", "Quilmes", "San Fernando", "San Isidro", "San Miguel", "San Vicente", "Tigre", "Tres de Febrero", "Vicente López", "Zárate",
        "Bahía Blanca", "Mar del Plata", "Junín", "Olavarría", "Tandil", "Necochea", "Pergamino", "Chivilcoy", "Azul", "Mercedes"
    ]; // Puedes completar la lista hasta los 135 partidos

    const listadoContainer = document.getElementById("listado-partidos");
    const busquedaInput = document.getElementById("busqueda");
    const verMasBtn = document.getElementById("ver-mas");
    const contador = document.getElementById("contador");

    let limiteVisible = 20;

    const renderizarPartidos = (filtro = "") => {
        if (!listadoContainer) return;

        const normalizar = (str) => str.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
        const filtrados = partidos.filter(p => normalizar(p).includes(normalizar(filtro)));

        const visibles = filtrados.slice(0, limiteVisible);

        listadoContainer.innerHTML = visibles.map(p =>
            `<div style="padding:10px; background:#fff; border:1px solid #dee2e6; border-radius:8px; font-size:0.9rem; color:#333;">
                <i class="fa-solid fa-location-dot me-2 text-primary" style="font-size:0.8rem;"></i>${p}
             </div>`
        ).join("");

        if (contador) {
            contador.innerHTML = `<small>Mostrando <strong>${visibles.length}</strong> de ${filtrados.length} localidades</small>`;
        }

        if (verMasBtn) {
            verMasBtn.style.display = (filtrados.length > limiteVisible) ? "inline-block" : "none";
        }
    };

    if (busquedaInput) {
        busquedaInput.addEventListener("input", (e) => {
            limiteVisible = 20;
            renderizarPartidos(e.target.value);
        });
    }

    if (verMasBtn) {
        verMasBtn.addEventListener("click", () => {
            limiteVisible += 40;
            renderizarPartidos(busquedaInput?.value || "");
        });
    }

    renderizarPartidos();

    // Lazy load carousel images on slide
    document.querySelectorAll('.carousel').forEach(carousel => {
        carousel.addEventListener('slide.bs.carousel', event => {
            const lazyImg = event.relatedTarget.querySelector('img[data-src]');
            if (lazyImg) {
                lazyImg.addEventListener('load', () => {
                    lazyImg.removeAttribute('data-src');
                }, { once: true });
                lazyImg.src = lazyImg.getAttribute('data-src');
            }
        });
    });
});